/**
 * Feature Reviewer Daemon (T4).
 *
 * Poll step that runs every FEATURE_REVIEW_INTERVAL cycles. For each
 * in_handoff feature it detects drift (new commits on the base branch since
 * the feature started) and routes to one of three outcomes:
 *
 *   1. No new commits → skip.
 *   2. New commits, no file overlap → auto-rebase feature branch onto base;
 *      on rebase conflict fall through to escalation.
 *   3. New commits, file overlap → optional Claude API semantic analysis
 *      (confidence ≥ threshold → treat as no-overlap/auto-rebase;
 *       confidence < threshold → feature-level escalation).
 *
 * Feature-level escalation:
 *   - Sets drift_detected: true + drift_reason in status.yaml on the feature branch.
 *   - POSTs to SLACK_WEBHOOK_URL if set; skips gracefully if absent.
 */

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import { curlJson } from "../utils/curl-json.js";
import {
  featuresRoot,
  featureBranchName,
  statusYamlAbsPath,
  statusYamlRelPath,
} from "../paths.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface RunFeatureReviewCycleOpts {
  workspaceRoot: string;
  baseBranch: string;
  mgmtRepoOwner: string;
  mgmtRepoName: string;
  githubToken: string;
  reviewerGithubToken?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  anthropicApiKey?: string;
  slackWebhookUrl?: string;
  /** Confidence threshold for semantic analysis. Default: 0.80. */
  semanticConfidenceThreshold?: number;
  emit: (event: Record<string, unknown>) => void;
}

interface StatusYaml {
  feature_status?: string;
  feature_branch?: string;
  feature_branch_base_sha?: string | null;
  handoff_pr_url?: string | null;
  impl_feature_prs?: ImplFeaturePr[];
  drift_detected?: boolean;
  drift_reason?: string | null;
  [key: string]: unknown;
}

interface ImplFeaturePr {
  repo: string;
  url: string;
  status: "open" | "merged";
}

interface GitHubCompareResult {
  ahead_by: number;
  files?: GitHubFile[];
  [key: string]: unknown;
}

interface GitHubFile {
  filename: string;
  status: string;
  [key: string]: unknown;
}

export interface SemanticAnalysisResult {
  confidence: number;
  hasConflict: boolean;
  reasoning: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const docsPath = featuresRoot(workspaceRoot);
  if (!existsSync(docsPath)) return [];
  try {
    return readdirSync(docsPath, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

